18.         0 <= raw as int <= FrameNumber::spec_max(),
19.     ensures
20.         (raw << crate::mem::FRAME_SHIFT) as int == raw as int * (crate::mem::FRAME_SIZE as int),
21.         (raw << crate::mem::FRAME_SHIFT) as int % (crate::mem::FRAME_SIZE as int) == 0,
22. {
23.     let s: int = crate::mem::FRAME_SIZE as int;
24.     let m: int = crate::mem::MAX_ADDRESS as int;
25. 
26.     // `pow2(FRAME_SHIFT) == FRAME_SIZE` (i.e. `pow2(12) == 4096`).
27.     lemma2_to64();
28.     assert(pow2(crate::mem::FRAME_SHIFT as nat) == crate::mem::FRAME_SIZE);
29. 
30.     // The product fits in `usize`: `raw <= m / s - 1`, and `(m / s) * s <= m`.
31.     lemma_mod_bound(m, s);
32.     lemma_fundamental_div_mod(m, s);
33.     lemma_mul_inequality(raw as int, m / s - 1, s);
34.     assert(raw as int * s <= m) by (nonlinear_arith)
